create extension if not exists pgcrypto;
create table if not exists public.teachers(user_id uuid primary key references auth.users(id) on delete cascade);
create table if not exists public.exams(id uuid primary key default gen_random_uuid(),title text not null,duration_minutes int not null check(duration_minutes between 1 and 300),active boolean default true,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.questions(id uuid primary key default gen_random_uuid(),exam_id uuid references public.exams(id) on delete cascade,position int,text text not null,choices jsonb not null,correct_index int not null,unique(exam_id,position));
create table if not exists public.attempts(id uuid primary key default gen_random_uuid(),token uuid unique default gen_random_uuid(),exam_id uuid references public.exams(id) on delete cascade,student_id text,student_name text,started_at timestamptz default now(),expires_at timestamptz,finished_at timestamptz,score int default 0,unique(exam_id,student_id));
create table if not exists public.answers(id uuid primary key default gen_random_uuid(),attempt_id uuid references public.attempts(id) on delete cascade,question_id uuid references public.questions(id),choice_index int,is_correct boolean,answered_at timestamptz default now(),unique(attempt_id,question_id));
alter table public.teachers enable row level security; alter table public.exams enable row level security; alter table public.questions enable row level security; alter table public.attempts enable row level security; alter table public.answers enable row level security;
revoke all on public.teachers,public.exams,public.questions,public.attempts,public.answers from anon,authenticated;
create or replace function public.is_teacher() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from teachers where user_id=auth.uid())$$;
create or replace function public.teacher_get_exam() returns jsonb language plpgsql security definer set search_path=public as $$declare e exams;r jsonb;begin if not is_teacher() then raise exception 'Unauthorized';end if;select * into e from exams order by created_at desc limit 1;if e.id is null then return null;end if;select jsonb_build_object('title',e.title,'durationMinutes',e.duration_minutes,'questions',coalesce(jsonb_agg(jsonb_build_object('text',q.text,'choices',q.choices,'correct',q.correct_index) order by q.position),'[]')) into r from questions q where q.exam_id=e.id;return r;end$$;
create or replace function public.teacher_save_exam(payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare eid uuid;x jsonb;n int:=0;begin if not is_teacher() then raise exception 'Unauthorized';end if;if jsonb_array_length(payload->'questions') not between 1 and 200 then raise exception 'จำนวนข้อไม่ถูกต้อง';end if;update exams set active=false where active;insert into exams(title,duration_minutes,active,created_by) values(payload->>'title',(payload->>'durationMinutes')::int,true,auth.uid()) returning id into eid;for x in select * from jsonb_array_elements(payload->'questions') loop insert into questions(exam_id,position,text,choices,correct_index) values(eid,n,x->>'text',x->'choices',(x->>'correct')::int);n=n+1;end loop;return jsonb_build_object('ok',true);end$$;
create or replace function public.get_active_exam() returns jsonb language sql security definer set search_path=public as $$select jsonb_build_object('title',e.title,'durationMinutes',e.duration_minutes,'questionCount',count(q.id)) from exams e join questions q on q.exam_id=e.id where e.active group by e.id limit 1$$;
create or replace function public.start_attempt(p_student_id text,p_student_name text) returns jsonb language plpgsql security definer set search_path=public as $$declare e exams;a attempts;t int;begin if trim(p_student_id)='' or trim(p_student_name)='' then raise exception 'กรุณากรอกชื่อและเลขประจำตัว';end if;select * into e from exams where active limit 1;if e.id is null then raise exception 'ยังไม่มีข้อสอบ';end if;select count(*) into t from questions where exam_id=e.id;select * into a from attempts where exam_id=e.id and student_id=trim(p_student_id);if a.id is null then insert into attempts(exam_id,student_id,student_name,expires_at) values(e.id,trim(p_student_id),trim(p_student_name),now()+make_interval(mins=>e.duration_minutes)) returning * into a;end if;return jsonb_build_object('token',a.token,'expiresAt',a.expires_at,'total',t);end$$;
create or replace function public.get_next_question(p_token uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare a attempts;q questions;n int;t int;begin select * into a from attempts where token=p_token;select count(*) into n from answers where attempt_id=a.id;select count(*) into t from questions where exam_id=a.exam_id;if a.finished_at is not null or n>=t or now()>a.expires_at then if a.finished_at is null then update attempts set finished_at=now() where id=a.id;end if;return jsonb_build_object('finished',true,'score',a.score,'total',t);end if;select * into q from questions where exam_id=a.exam_id order by position offset n limit 1;return jsonb_build_object('finished',false,'number',n+1,'total',t,'text',q.text,'choices',q.choices,'expiresAt',a.expires_at);end$$;
create or replace function public.submit_answer(p_token uuid,p_choice int) returns jsonb language plpgsql security definer set search_path=public as $$declare a attempts;q questions;n int;t int;c boolean;s int;begin select * into a from attempts where token=p_token for update;if a.finished_at is not null or now()>a.expires_at then raise exception 'หมดเวลาหรือส่งแล้ว';end if;select count(*) into n from answers where attempt_id=a.id;select count(*) into t from questions where exam_id=a.exam_id;select * into q from questions where exam_id=a.exam_id order by position offset n limit 1;c=p_choice=q.correct_index;insert into answers(attempt_id,question_id,choice_index,is_correct) values(a.id,q.id,p_choice,c);s=a.score+case when c then 1 else 0 end;update attempts set score=s,finished_at=case when n+1>=t then now() else null end where id=a.id;return jsonb_build_object('correct',c,'correctChoice',q.correct_index,'correctText',q.choices->>q.correct_index,'finished',n+1>=t,'score',s,'total',t);end$$;
create or replace function public.teacher_get_results() returns jsonb language plpgsql security definer set search_path=public as $$declare r jsonb;begin if not is_teacher() then raise exception 'Unauthorized';end if;select coalesce(jsonb_agg(jsonb_build_object('studentId',a.student_id,'studentName',a.student_name,'finishedAt',a.finished_at,'score',a.score,'total',(select count(*) from questions q where q.exam_id=a.exam_id),'answers',coalesce((select jsonb_agg(jsonb_build_object('question',q.position+1,'choice',z.choice_index,'correct',z.is_correct) order by q.position) from answers z join questions q on q.id=z.question_id where z.attempt_id=a.id),'[]')) order by a.started_at desc),'[]') into r from attempts a where a.exam_id=(select id from exams order by created_at desc limit 1);return r;end$$;
grant execute on function public.get_active_exam() to anon,authenticated;grant execute on function public.start_attempt(text,text) to anon,authenticated;grant execute on function public.get_next_question(uuid) to anon,authenticated;grant execute on function public.submit_answer(uuid,int) to anon,authenticated;grant execute on function public.teacher_get_exam() to authenticated;grant execute on function public.teacher_save_exam(jsonb) to authenticated;grant execute on function public.teacher_get_results() to authenticated;
